CREATE OR REPLACE FUNCTION prevent_active_with_failed_inspection()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.OPER_status = 'Active' AND NEW.inspect_status = 'Failed' THEN
        RAISE EXCEPTION 'Equipment cannot be set to Active status with Failed inspection status';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_prevent_active_failed_inspection
BEFORE UPDATE ON OperationMaintenance
FOR EACH ROW
WHEN (OLD.OPER_status IS DISTINCT FROM NEW.OPER_status OR OLD.inspect_status IS DISTINCT FROM NEW.inspect_status)
EXECUTE FUNCTION prevent_active_with_failed_inspection();

